CREATE TABLE work_records(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,requester_id TEXT NOT NULL,beneficiary_id TEXT NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open',sensitivity TEXT NOT NULL DEFAULT 'normal',assignee_id TEXT,impact TEXT NOT NULL DEFAULT 'individual',revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,closed_at TEXT,paused_at TEXT,paused_ms INTEGER NOT NULL DEFAULT 0,response_at TEXT,resolution_at TEXT,context_json TEXT NOT NULL DEFAULT '{}',dedup_key TEXT NOT NULL,UNIQUE(workspace_id,requester_id,dedup_key));
CREATE TABLE work_messages(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,author_id TEXT NOT NULL,visibility TEXT NOT NULL,body TEXT NOT NULL,source_key TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(workspace_id,work_id,source_key));
CREATE TABLE work_attachments(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,visibility TEXT NOT NULL,blob_key TEXT NOT NULL,name TEXT NOT NULL,content_type TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE work_people(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,source TEXT NOT NULL,source_id TEXT NOT NULL,name TEXT NOT NULL,manager_id TEXT,active INTEGER NOT NULL DEFAULT 1,merged_into TEXT,revision INTEGER NOT NULL DEFAULT 1,observed_at TEXT NOT NULL,effective_at TEXT NOT NULL,UNIQUE(workspace_id,source,source_id));
CREATE TABLE work_assets(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,serial TEXT NOT NULL,state TEXT NOT NULL,person_id TEXT,location TEXT,source TEXT NOT NULL,observed_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,serial));
CREATE TABLE work_custody(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,asset_id TEXT NOT NULL,actor_id TEXT NOT NULL,kind TEXT NOT NULL,person_id TEXT,evidence TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE work_lifecycle(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,person_id TEXT NOT NULL,kind TEXT NOT NULL,effective_at TEXT NOT NULL,timezone TEXT NOT NULL,source TEXT NOT NULL,source_revision INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,cancelled_at TEXT,UNIQUE(workspace_id,source,person_id,source_revision));
CREATE TABLE work_obligations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,lifecycle_id TEXT,kind TEXT NOT NULL,target TEXT NOT NULL,beneficiary_id TEXT NOT NULL,due_at TEXT NOT NULL,depends_on TEXT,state TEXT NOT NULL DEFAULT 'pending',owner_id TEXT,operation_id TEXT,last_error TEXT,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,work_id,kind,target));
CREATE TABLE work_knowledge(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,scope TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,reviewer_id TEXT,reviewed_at TEXT,expires_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE work_erasure(workspace_id TEXT NOT NULL,person_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,person_id));
CREATE INDEX work_due ON work_obligations(state,due_at);
